	n := len(nums)
	subsets := [][]int{}
	for mask := 0; mask < 1<<n; mask++ {
		subset := []int{}
		for i := 0; i < n; i++ {
			if (mask>>i)&1 == 1 {
				subset = append(subset, nums[i])
			}
		}
		subsets = append(subsets, subset)
	}
	return subsets
}

